// Generated by `npm run voices`. One entry per recorded line: key = hash(voice, mood, text).
export interface VoiceClip {
  /** File in voices/ (16-bit mono WAV). */
  file: string;
  duration: number;
  /** Loudness for lip sync, 60 samples per second. */
  envelope: string;
  provider: string;
  voice: string;
  text: string;
}

export const VOICE_CLIPS: Record<string, VoiceClip> = {};
